package org.marketreview.nativeapp;
import android.content.Context;
import android.view.*;
import android.widget.*;
import android.text.*;
import java.io.File;
import java.util.*;
import org.json.*;

final class PaperAutomationScreen extends LinearLayout {
 final PaperAutomationRuntime runtime;final PaperAutomationRuntime.Host host;Runnable back;
 private boolean active,filling,dirty;private AiKnowledgeRequest.Prepared plan;private final CheckBox openingAck,enabled,simulation,nextDay;
 private final EditText schedule,maxPositions,reserve;private final TextView summary,status,reader,pageStatus;
 private final Spinner records;private RequestAuthorizationView authorization;private final Button initialize,save,prepare,preview,start,poll;
 private final List<String> recordIds=new ArrayList<>();private String fullText="";private int page;
 private final LinearLayout main;private final ScrollView controlsScroll,readerScroll;
 interface Checked{void run()throws Exception;}
 PaperAutomationScreen(Context c,File file,String account,PaperAutomationRuntime.Host host)throws Exception{
  super(c);this.host=host;runtime=new PaperAutomationRuntime(file,account,host);setOrientation(VERTICAL);setTag("paperAutomationPage");setSaveEnabled(false);
  main=new LinearLayout(c);main.setOrientation(VERTICAL);addView(main,new LayoutParams(-1,0,1));controlsScroll=new ScrollView(c);LinearLayout controls=new LinearLayout(c);controls.setOrientation(VERTICAL);controlsScroll.addView(controls);main.addView(controlsScroll,new LayoutParams(-1,0,3));
  button(controls,"返回人工纸面监控","paperAutomationBack",()->{if(back!=null)back.run();});
  label(controls,"纸面自动监控 / 模拟成交 · "+account,null);
  label(controls,"仅在此页前台启用时，按交易日时段监控并刷新公开行情。每次分析须核对材料并授权；离页取消当前任务及未成交订单。仅记纸面执行账本。",null);
  summary=label(controls,"","paperAutomationSummary");openingAck=check(controls,"已核对该纸面账户、起始人工现金及完整持仓流水","paperAutomationOpeningAck");initialize=button(controls,"建立纸面执行账本（默认关闭）","paperAutomationInitialize",()->{if(!openingAck.isChecked())throw new Exception("请核对起始纸面范围");runtime.initialize(settings(true));openingAck.setChecked(false);});
  enabled=check(controls,"启用前台时段监控及公开行情刷新","paperAutomationEnabled");simulation=check(controls,"启用本机纸面订单模拟成交","paperAutomationSimulation");nextDay=check(controls,"从下一交易日开始","paperAutomationNextDay");
  schedule=edit(controls,"上海时区时点（逗号分隔）","09:35,10:30,14:50","paperAutomationSchedule");maxPositions=edit(controls,"最大持股数（1–20）","8","paperAutomationMaxPositions");reserve=edit(controls,"保留现金比例（0–90%）","20","paperAutomationReserve");
  save=button(controls,"保存执行设置","paperAutomationSave",()->{JSONObject s=settings(false);authorization.clear();plan=null;runtime.configure(s);dirty=false;render();});
  prepare=button(controls,"立即准备一次分析","paperAutomationPrepare",()->{authorization.clear();plan=null;runtime.prepare();});preview=button(controls,"预览本次精确 AI 请求","paperAutomationPreview",()->{plan=runtime.request();authorization.bind(Collections.singletonList(plan));});
  authorization=new RequestAuthorizationView(c,this::usable);controls.addView(authorization);start=button(controls,"开始本次已授权分析","paperAutomationStart",()->{if(plan==null||!authorization.ready())throw new Exception("请先预览并授权本次请求");runtime.start(plan,authorization.authorize(plan),authorization::acquire);});
  poll=button(controls,"核对当前时段和待成交订单","paperAutomationPoll",runtime::tick);button(controls,"取消当前任务和未成交订单","paperAutomationCancel",()->{authorization.clear();plan=null;runtime.cancel("user-cancelled");});
  LinearLayout reading=new LinearLayout(c);reading.setOrientation(VERTICAL);main.addView(reading,new LayoutParams(-1,0,2));status=label(controls,"","paperAutomationStatus");records=new Spinner(c);records.setTag("paperAutomationRecords");records.setSaveEnabled(false);reading.addView(records);
  LinearLayout pages=new LinearLayout(c);reading.addView(pages);button(pages,"上一页",null,()->{if(page>0){page--;showText();}});pageStatus=label(pages,"",null);pageStatus.setLayoutParams(new LayoutParams(0,-2,1));button(pages,"下一页",null,()->{if((page+1)*20000<fullText.length()){page++;showText();}});
  readerScroll=new ScrollView(c);reader=label(new LinearLayout(c),"","paperAutomationReader");((android.view.ViewGroup)reader.getParent()).removeView(reader);reader.setTextIsSelectable(true);readerScroll.addView(reader);reading.addView(readerScroll,new LayoutParams(-1,0,1));arrange(reading);
  for(CheckBox box:new CheckBox[]{enabled,simulation,nextDay})box.setOnCheckedChangeListener((b,on)->{if(!filling)dirty=true;});for(EditText box:new EditText[]{schedule,maxPositions,reserve})box.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){if(!filling)dirty=true;}});
  records.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?>p){}public void onItemSelected(AdapterView<?>p,View v,int n,long id){if(!filling)guard(()->readRecord());}});
  runtime.changed=()->guard(this::render);authorization.changed=()->{if(start!=null)start.setEnabled(usable()&&plan!=null&&authorization.ready()&&!runtime.busy());};authorization.expired=()->{plan=null;guard(()->runtime.cancel("authorization-withdrawn-or-expired"));};render();
 }
 private TextView label(LinearLayout parent,String text,String tag){TextView v=new TextView(getContext()){@Override public boolean onPreDraw(){return !isShown()||getWidth()<=0||super.onPreDraw();}};v.setBreakStrategy(android.text.Layout.BREAK_STRATEGY_SIMPLE);v.setHyphenationFrequency(android.text.Layout.HYPHENATION_FREQUENCY_NONE);v.setText(text);v.setSaveEnabled(false);if(tag!=null)v.setTag(tag);parent.addView(v,new LayoutParams(-1,-2));return v;}
 private CheckBox check(LinearLayout p,String text,String tag){CheckBox c=new CheckBox(getContext());c.setText(text);c.setTag(tag);c.setSaveEnabled(false);p.addView(c);return c;}
 private EditText edit(LinearLayout p,String text,String initial,String tag){label(p,text,null);EditText e=new EditText(getContext());e.setSingleLine(true);e.setText(initial);e.setTag(tag);e.setSaveEnabled(false);p.addView(e);return e;}
 private Button button(LinearLayout p,String text,String tag,Checked action){Button b=new Button(getContext());b.setText(text);b.setTextSize(12);b.setTag(tag);p.addView(b,p.getOrientation()==VERTICAL?new LayoutParams(-1,-2):new LayoutParams(0,-2,1));b.setOnClickListener(v->{if(usable())guard(action);});return b;}
 private void guard(Checked action){try{action.run();}catch(Exception e){status.setText("已阻断："+e.getMessage());start.setEnabled(false);}}
 private boolean usable(){return active&&isShown()&&hasWindowFocus();}
 private JSONObject settings(boolean initial)throws Exception{JSONArray times=new JSONArray();for(String t:schedule.getText().toString().split(","))times.put(t.trim());JSONObject prior=runtime.book().optJSONObject("settings");String mode=nextDay.isChecked()?"next-trading-day":"today";boolean activation=initial||prior==null||prior.getBoolean("enabled")!=enabled.isChecked()||!mode.equals(prior.getString("startMode"));return PaperAutomationModel.obj("enabled",!initial&&enabled.isChecked(),"simulationEnabled",!initial&&simulation.isChecked(),"startMode",mode,"activatedAt",activation?host.now():prior.getString("activatedAt"),"schedule",times,"maxPositions",Integer.parseInt(maxPositions.getText().toString()),"cashReserve",Double.parseDouble(reserve.getText().toString())/100,"candidateIds",new JSONArray());}
 private void render()throws Exception{JSONObject b=runtime.book();boolean exists=b.length()>0;initialize.setEnabled(usable()&&!exists);openingAck.setEnabled(!exists);for(Button button:new Button[]{save,prepare,preview,poll})button.setEnabled(usable()&&exists&&!runtime.busy());start.setEnabled(usable()&&plan!=null&&authorization.ready()&&!runtime.busy());status.setText(runtime.message());if(!exists){summary.setText("尚未建立纸面执行账本。原账户、手工现金和人工分析归档仍保留。");return;}
  JSONObject s=b.getJSONObject("settings");filling=true;if(!dirty){enabled.setChecked(s.getBoolean("enabled"));simulation.setChecked(s.getBoolean("simulationEnabled"));nextDay.setChecked(s.getString("startMode").equals("next-trading-day"));List<String> times=new ArrayList<>();for(int i=0;i<s.getJSONArray("schedule").length();i++)times.add(s.getJSONArray("schedule").getString(i));schedule.setText(String.join(",",times));maxPositions.setText(Integer.toString(s.getInt("maxPositions")));reserve.setText(Double.toString(s.getDouble("cashReserve")*100));}
  JSONObject opening=b.getJSONObject("openingInput").getJSONObject("account");summary.setText(String.format(Locale.ROOT,"起始现金：%.2f（%s / %s）\n纸面执行余额：%.2f\n订单 %d · 成交 %d\n持仓及成本可回看；缺少当前行情覆盖时不显示新鲜净值。",opening.getDouble("cashBalance"),opening.getString("cashSource").equals("manual")?"人工登记":"纸面流水",opening.getString("cashVerification").equals("unverified")?"未独立核验":"账本已核对",b.getDouble("cash"),b.getJSONArray("orders").length(),b.getJSONArray("fills").length()));
  int selected=records.getSelectedItemPosition();String key=selected>=0&&selected<recordIds.size()?recordIds.get(selected):"overview";List<String>labels=new ArrayList<>();recordIds.clear();recordIds.add("overview");labels.add("执行余额与持仓");recordIds.add("evidence");labels.add("完整起始依据（核对记录）");JSONObject tasks=b.getJSONObject("tasks");for(String id:PaperAutomationModel.keys(tasks)){JSONObject t=tasks.getJSONObject(id);recordIds.add("task:"+id);labels.add("分析 "+t.getString("startedAt")+" / "+t.getString("status"));}recordIds.add("slots");labels.add("交易时段及重试记录");recordIds.add("execution");labels.add("纸面订单与模拟成交");records.setAdapter(new ArrayAdapter<>(getContext(),android.R.layout.simple_spinner_dropdown_item,labels));records.setSelection(Math.max(0,recordIds.indexOf(key)));filling=false;readRecord();
 }
 private void readRecord()throws Exception{JSONObject b=runtime.book();if(b.length()==0)return;int n=records.getSelectedItemPosition();String key=n>=0&&n<recordIds.size()?recordIds.get(n):"overview";if(key.equals("overview")){String text=ledgerText(b);if(!text.equals(fullText)){fullText=text;page=0;}showText();return;}JSONObject item;if(key.startsWith("task:"))item=b.getJSONObject("tasks").getJSONObject(key.substring(5));else if(key.equals("slots"))item=b.getJSONObject("slots");else if(key.equals("execution"))item=PaperAutomationModel.obj("orders",b.get("orders"),"fills",b.get("fills"),"snapshots",b.get("snapshots"));else item=PaperAutomationModel.obj("accountId",b.get("accountId"),"cash",b.get("cash"),"positions",b.get("positions"),"createdAt",b.get("createdAt"),"openingInput",b.get("openingInput"),"openingHash",b.get("openingHash"));String text=item.toString(2);if(!text.equals(fullText)){fullText=text;page=0;}showText();}
 private String ledgerText(JSONObject b)throws Exception{JSONObject opening=b.getJSONObject("openingInput").getJSONObject("account");StringBuilder text=new StringBuilder("纸面执行概览\n账户："+opening.getString("name")+"（"+b.getString("accountId")+"）\n");text.append(String.format(Locale.ROOT,"可用纸面现金：%.2f 元\n",b.getDouble("cash"))).append("建立时间：").append(b.getString("createdAt")).append("\n\n当前纸面持仓（成本口径）\n");JSONObject ps=b.getJSONObject("positions");for(String id:PaperAutomationModel.keys(ps)){JSONObject p=ps.getJSONObject(id);if(p.getDouble("quantity")<=0)continue;text.append(p.getString("name")).append(" · ").append(id).append(String.format(Locale.ROOT,"\n数量 %.0f 股 · 剩余成本 %.2f 元 · 累计已实现损益 %.2f 元\n\n",p.getDouble("quantity"),p.getDouble("cost"),p.getDouble("realized")));}return text.append("起始现金和持仓来自所选账户及人工流水，模拟成交只计入本页账本。\n这里的剩余成本不代表当前市值；没有完整行情覆盖时不显示实时净值。\n完整起始材料、订单、成交和分析原文可从上方列表选择回看。").toString();}
 private void showText(){int from=page*20000,to=Math.min(fullText.length(),from+20000);if(from>0&&from<fullText.length()&&Character.isLowSurrogate(fullText.charAt(from)))from--;if(to<fullText.length()&&Character.isLowSurrogate(fullText.charAt(to)))to--;reader.setText(fullText.substring(from,to));pageStatus.setText("第 "+(page+1)+" / "+Math.max(1,(fullText.length()+19999)/20000)+" 页 · 全文保留");readerScroll.scrollTo(0,0);}
 void setActive(boolean value){active=value;if(!value){authorization.clear();plan=null;openingAck.setChecked(false);}guard(()->{runtime.setActive(value);render();});}
 private void arrange(LinearLayout reading){boolean wide=getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE;main.setOrientation(wide?HORIZONTAL:VERTICAL);controlsScroll.setLayoutParams(wide?new LayoutParams(0,-1,1):new LayoutParams(-1,0,3));reading.setLayoutParams(wide?new LayoutParams(0,-1,1):new LayoutParams(-1,0,2));}
 @Override protected void onConfigurationChanged(android.content.res.Configuration c){super.onConfigurationChanged(c);if(main!=null&&main.getChildCount()>1)arrange((LinearLayout)main.getChildAt(1));}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(runtime!=null&&status!=null)setActive(focus&&isShown());}
 @Override protected void onDetachedFromWindow(){if(runtime!=null)setActive(false);super.onDetachedFromWindow();}
}
